  const analyzeText = async (textToAnalyze) => {
  if (!textToAnalyze || textToAnalyze.length < 10) {
    setEntities([]);
    setConfidence(0);
    return;
  }

  if (!serverSettings?.url) {
    console.warn('Server URL not configured');
    return;
  }

  try {
    const response = await fetch(`${serverSettings.url}/analyze`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        texts: [textToAnalyze], // важно: 'texts', а не 'text'!
        include_tokens: serverSettings.includeTokens || false
      })
    });

    if (response.ok) {
      const result = await response.json();

      const transformedEntities = result.results.flatMap(entry =>
        entry.paragraphs.map(p => ({
          text: p.paragraph,
          label: p.label,
          confidence: p.confidence || 0.85
        }))
      );

      const avgConfidence = transformedEntities.length > 0 
        ? Math.round(transformedEntities.reduce((sum, e) => sum + (e.confidence || 0), 0) / transformedEntities.length * 100)
        : 0;

      setEntities(transformedEntities);
      setConfidence(avgConfidence);

      if (onAnalysisUpdate) {
        onAnalysisUpdate({
          entities: transformedEntities,
          entityCount: transformedEntities.length,
          confidence: avgConfidence,
          processedAt: result.processed_at,
          tokens: result.tokens || []
        });
      }

      console.log('NLP Analysis completed:', result);
    } else {
      const error = await response.json();
      console.error('Analysis failed:', error);
      setEntities([]);
      setConfidence(0);
    }
  } catch (error) {
    console.error('Analysis error:', error);
    setEntities([]);
    setConfidence(0);
  }
};


