import React, { useState } from 'react';
import {
  Box,
  Paper,
  TextField,
  Button,
  Typography,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  Grid
} from '@mui/material';

const ProtocolValidator = () => {
  const [formData, setFormData] = useState({
    mkb10: '',
    diagType: '',
    diagChar: '',
    diagVid: '',
    reason: '',
    serviceCode: '',
    place: '',
    age: '',
    sex: 'M',
    insured: true
  });

  // Определения типов диагнозов для подсказок
  const diagnosisTypes = {
    1: 'Направительный',
    2: 'Предварительный',
    3: 'Этапный',
    4: 'Клинический',
    5: 'Патологоанатомический',
    6: 'Судебно-медицинский',
    7: 'Заключительный',
    8: 'Прочий',
    9: 'Посмертный'
  };

  const diagnosisCharacters = {
    1: 'Острое заболевание',
    2: 'Хроническое впервые',
    3: 'Хроническое повторно',
    4: 'Хроническое обострение'
  };

  const diagnosisKinds = {
    1: 'Основной',
    2: 'Осложнение',
    3: 'Сопутствующий',
    4: 'Связанный с основным',
    5: 'Конкурирующий',
    6: 'Фоновый'
  };

  const [validationResult, setValidationResult] = useState(null);

  const handleChange = (field) => (event) => {
    setFormData({
      ...formData,
      [field]: event.target.value
    });
  };

  const handleValidate = () => {
    // Convert numeric fields from string to number
    const dataToValidate = {
      ...formData,
      diagType: Number(formData.diagType),
      diagChar: Number(formData.diagChar),
      diagVid: Number(formData.diagVid),
      reason: Number(formData.reason),
      age: Number(formData.age)
    };

    const result = window.ProtocolValidator.validateCase(dataToValidate);
    setValidationResult(result);
  };

  return (
    <Paper elevation={3} sx={{ p: 3, mt: 3 }}>
      <Typography variant="h5" gutterBottom>
        Валидация протокола МКБ
      </Typography>

      <Grid container spacing={2}>
        <Grid item xs={12} sm={6} md={4}>
          <TextField
            fullWidth
            label="Код МКБ-10"
            value={formData.mkb10}
            onChange={handleChange('mkb10')}
            margin="normal"
          />
        </Grid>

        <Grid item xs={12} sm={6} md={4}>
          <FormControl fullWidth margin="normal">
            <InputLabel>Тип диагноза</InputLabel>
            <Select
              value={formData.diagType}
              onChange={handleChange('diagType')}
              label="Тип диагноза"
            >
              {Object.entries(diagnosisTypes).map(([value, label]) => (
                <MenuItem key={value} value={Number(value)}>
                  {value} - {label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12} sm={6} md={4}>
          <FormControl fullWidth margin="normal">
            <InputLabel>Характер диагноза</InputLabel>
            <Select
              value={formData.diagChar}
              onChange={handleChange('diagChar')}
              label="Характер диагноза"
            >
              {Object.entries(diagnosisCharacters).map(([value, label]) => (
                <MenuItem key={value} value={Number(value)}>
                  {value} - {label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12} sm={6} md={4}>
          <FormControl fullWidth margin="normal">
            <InputLabel>Вид диагноза</InputLabel>
            <Select
              value={formData.diagVid}
              onChange={handleChange('diagVid')}
              label="Вид диагноза"
            >
              {Object.entries(diagnosisKinds).map(([value, label]) => (
                <MenuItem key={value} value={Number(value)}>
                  {value} - {label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12} sm={6} md={4}>
          <FormControl fullWidth margin="normal">
            <InputLabel>Повод обращения</InputLabel>
            <Select
              value={formData.reason}
              onChange={handleChange('reason')}
              label="Повод обращения"
            >
              <MenuItem value={13}>Острая травма (13)</MenuItem>
              <MenuItem value={14}>Последствия травмы (14)</MenuItem>
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12} sm={6} md={4}>
          <TextField
            fullWidth
            label="Код услуги"
            value={formData.serviceCode}
            onChange={handleChange('serviceCode')}
            margin="normal"
          />
        </Grid>

        <Grid item xs={12} sm={6} md={4}>
          <FormControl fullWidth margin="normal">
            <InputLabel>Место оказания</InputLabel>
            <Select
              value={formData.place}
              onChange={handleChange('place')}
              label="Место оказания"
            >
              <MenuItem value="С">Стационар (С)</MenuItem>
              <MenuItem value="П">Поликлиника (П)</MenuItem>
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12} sm={6} md={4}>
          <TextField
            fullWidth
            label="Возраст"
            type="number"
            value={formData.age}
            onChange={handleChange('age')}
            margin="normal"
          />
        </Grid>

        <Grid item xs={12} sm={6} md={4}>
          <FormControl fullWidth margin="normal">
            <InputLabel>Пол</InputLabel>
            <Select
              value={formData.sex}
              onChange={handleChange('sex')}
              label="Пол"
            >
              <MenuItem value="M">Мужской</MenuItem>
              <MenuItem value="F">Женский</MenuItem>
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12}>
          <Button
            variant="contained"
            color="primary"
            onClick={handleValidate}
            sx={{ mt: 2 }}
          >
            Проверить
          </Button>
        </Grid>

        {validationResult && (
          <Grid item xs={12}>
            {validationResult.errors.length > 0 ? (
              validationResult.errors.map((error, index) => (
                <Alert severity="error" key={index} sx={{ mt: 1 }}>
                  {error}
                </Alert>
              ))
            ) : (
              <Alert severity="success" sx={{ mt: 1 }}>
                Протокол валиден
              </Alert>
            )}
          </Grid>
        )}
      </Grid>
    </Paper>
  );
};

export default ProtocolValidator;
