import React from 'react';
import {
  Paper,
  Typography,
  Box,
  Avatar,
  Chip,
  IconButton,
  Divider
} from '@mui/material';
import {
  Person,
  Edit,
  LocalHospital,
  AccessTime,
  Assignment
} from '@mui/icons-material';

const PatientInfoCard = ({ patientInfo, onEdit }) => {
  const getInitials = (name) => {
    return name
      .split(' ')
      .map(word => word[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Не указано';
    const date = new Date(dateString);
    return date.toLocaleDateString('ru-RU');
  };

  return (
    <Paper elevation={2} sx={{ p: 2 }}>
      <Box display="flex" alignItems="center" justifyContent="space-between" mb={2}>
        <Typography variant="h6" component="h2">
          <LocalHospital sx={{ mr: 1, verticalAlign: 'middle' }} />
          Пациент
        </Typography>
        <IconButton onClick={onEdit} size="small">
          <Edit />
        </IconButton>
      </Box>

      <Box display="flex" alignItems="center" mb={2}>
        <Avatar
          sx={{
            width: 56,
            height: 56,
            bgcolor: 'primary.main',
            mr: 2,
            fontSize: '1.2rem'
          }}
        >
          {patientInfo.name ? getInitials(patientInfo.name) : <Person />}
        </Avatar>
        <Box>
          <Typography variant="h6" component="div">
            {patientInfo.name || 'Пациент не указан'}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            ID: {patientInfo.id || 'Не указан'}
          </Typography>
        </Box>
      </Box>

      <Divider sx={{ my: 2 }} />

      <Box display="flex" flexDirection="column" gap={1}>
        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="body2" color="text.secondary">
            Дата рождения:
          </Typography>
          <Typography variant="body2">
            {formatDate(patientInfo.birthDate)}
          </Typography>
        </Box>

        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="body2" color="text.secondary">
            Лечащий врач:
          </Typography>
          <Typography variant="body2">
            {patientInfo.doctorName || 'Не указан'}
          </Typography>
        </Box>

        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="body2" color="text.secondary">
            Тип сессии:
          </Typography>
          <Chip
            label={patientInfo.sessionType}
            size="small"
            color="primary"
            variant="outlined"
          />
        </Box>

        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="body2" color="text.secondary">
            Дата сессии:
          </Typography>
          <Typography variant="body2">
            {formatDate(patientInfo.sessionDate)}
          </Typography>
        </Box>
      </Box>
    </Paper>
  );
};

export default PatientInfoCard;
