import React from 'react';
import {
  Box,
  Chip,
  IconButton,
  Tooltip,
  Typography
} from '@mui/material';
import {
  Cloud,
  CloudOff,
  Settings,
  Wifi,
  WifiOff
} from '@mui/icons-material';

const ServerStatus = ({ connected, url, onSettingsClick }) => {
  const getStatusIcon = () => {
    return connected ? <Cloud /> : <CloudOff />;
  };

  const getStatusColor = () => {
    return connected ? 'success' : 'error';
  };

  const getStatusText = () => {
    return connected ? 'Подключен к серверу' : 'Сервер недоступен';
  };

  const getTooltipText = () => {
    return connected 
      ? `Подключено к серверу: ${url}`
      : `Нет подключения к серверу: ${url}\nНажмите для настройки`;
  };

  return (
    <Box display="flex" alignItems="center" gap={1}>
      <Chip
        icon={getStatusIcon()}
        label={getStatusText()}
        color={getStatusColor()}
        variant="filled"
        size="small"
        sx={{ color: 'white' }}
      />
      <Tooltip title={`Сервер: ${url}`}>
        <Typography variant="caption" sx={{ color: 'white', maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis' }}>
          {url}
        </Typography>
      </Tooltip>
      <Tooltip title="Настройки сервера">
        <IconButton size="small" onClick={onSettingsClick} sx={{ color: 'white' }}>
          <Settings />
        </IconButton>
      </Tooltip>
    </Box>
  );
};

export default ServerStatus;
