import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Box,
  Typography,
  Grid,
  Switch,
  FormControlLabel,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Chip,
  Divider,
  Tabs,
  Tab,
  Alert,
  CircularProgress
} from '@mui/material';
import {
  Settings,
  Cloud,
  Mic,
  Security,
  Wifi,
  Check,
  Error
} from '@mui/icons-material';

const SettingsDialog = ({
  open,
  onClose,
  serverSettings,
  recordingSettings,
  onServerSettingsChange,
  onRecordingSettingsChange,
  onTestConnection
}) => {
  const [activeTab, setActiveTab] = useState(0);
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState(null);

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  const handleServerChange = (field, value) => {
    onServerSettingsChange({
      ...serverSettings,
      [field]: value
    });
  };

  const handleRecordingChange = (field, value) => {
    onRecordingSettingsChange({
      ...recordingSettings,
      [field]: value
    });
  };

  const testConnection = async () => {
    setTesting(true);
    setTestResult(null);
    
    try {
      // Simulate connection test
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // Mock test result
      const success = Math.random() > 0.3;
      setTestResult({
        success,
        message: success ? 'Соединение установлено' : 'Ошибка подключения'
      });
      
      onTestConnection();
    } catch (error) {
      setTestResult({
        success: false,
        message: 'Ошибка тестирования'
      });
    } finally {
      setTesting(false);
    }
  };

  const TabPanel = ({ children, value, index }) => (
    <div hidden={value !== index} style={{ paddingTop: 16 }}>
      {value === index && children}
    </div>
  );

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: { height: '80vh' }
      }}
    >
      <DialogTitle>
        <Box display="flex" alignItems="center">
          <Settings sx={{ mr: 1 }} />
          Настройки приложения
        </Box>
      </DialogTitle>

      <DialogContent>
        <Tabs value={activeTab} onChange={handleTabChange}>
          <Tab icon={<Cloud />} label="Сервер" />
          <Tab icon={<Mic />} label="Запись" />
          <Tab icon={<Security />} label="Безопасность" />
        </Tabs>

        {/* Server Settings Tab */}
        <TabPanel value={activeTab} index={0}>
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                Настройки NLP сервера
              </Typography>
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="URL сервера"
                value={serverSettings.url}
                onChange={(e) => handleServerChange('url', e.target.value)}
                placeholder="http://localhost:5000"
                helperText="Адрес сервера обработки речи"
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Язык распознавания</InputLabel>
                <Select
                  value={serverSettings.language}
                  onChange={(e) => handleServerChange('language', e.target.value)}
                  label="Язык распознавания"
                >
                  <MenuItem value="ru-RU">Русский</MenuItem>
                  <MenuItem value="en-US">English (US)</MenuItem>
                  <MenuItem value="en-GB">English (UK)</MenuItem>
                  <MenuItem value="de-DE">Deutsch</MenuItem>
                  <MenuItem value="fr-FR">Français</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} sm={6}>
              <FormControlLabel
                control={
                  <Switch
                    checked={serverSettings.includeTokens}
                    onChange={(e) => handleServerChange('includeTokens', e.target.checked)}
                  />
                }
                label="Включить анализ токенов"
              />
            </Grid>

            <Grid item xs={12}>
              <Divider />
            </Grid>

            <Grid item xs={12}>
              <Box display="flex" alignItems="center" gap={2}>
                <Button
                  variant="outlined"
                  startIcon={testing ? <CircularProgress size={16} /> : <Wifi />}
                  onClick={testConnection}
                  disabled={testing}
                >
                  {testing ? 'Тестирование...' : 'Тест соединения'}
                </Button>

                {testResult && (
                  <Chip
                    icon={testResult.success ? <Check /> : <Error />}
                    label={testResult.message}
                    color={testResult.success ? 'success' : 'error'}
                  />
                )}
              </Box>
            </Grid>

            {testResult && !testResult.success && (
              <Grid item xs={12}>
                <Alert severity="error">
                  Не удается подключиться к серверу. Проверьте URL и убедитесь, что сервер запущен.
                </Alert>
              </Grid>
            )}
          </Grid>
        </TabPanel>

        {/* Recording Settings Tab */}
        <TabPanel value={activeTab} index={1}>
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                Настройки записи аудио
              </Typography>
            </Grid>

            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Качество записи</InputLabel>
                <Select
                  value={recordingSettings.quality}
                  onChange={(e) => handleRecordingChange('quality', e.target.value)}
                  label="Качество записи"
                >
                  <MenuItem value="low">Низкое (8kHz)</MenuItem>
                  <MenuItem value="medium">Среднее (16kHz)</MenuItem>
                  <MenuItem value="high">Высокое (44kHz)</MenuItem>
                  <MenuItem value="professional">Профессиональное (96kHz)</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} sm={6}>
              <FormControlLabel
                control={
                  <Switch
                    checked={recordingSettings.noiseReduction}
                    onChange={(e) => handleRecordingChange('noiseReduction', e.target.checked)}
                  />
                }
                label="Подавление шума"
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <FormControlLabel
                control={
                  <Switch
                    checked={recordingSettings.autoSave}
                    onChange={(e) => handleRecordingChange('autoSave', e.target.checked)}
                  />
                }
                label="Автосохранение"
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                type="number"
                label="Интервал автосохранения (сек)"
                value={recordingSettings.autoSaveInterval / 1000}
                onChange={(e) => handleRecordingChange('autoSaveInterval', parseInt(e.target.value) * 1000)}
                disabled={!recordingSettings.autoSave}
                inputProps={{ min: 30, max: 600 }}
              />
            </Grid>

            <Grid item xs={12}>
              <Divider />
            </Grid>

            <Grid item xs={12}>
              <Alert severity="info">
                <Typography variant="subtitle2" gutterBottom>
                  Рекомендации для медицинской записи:
                </Typography>
                <Typography variant="body2">
                  • Используйте высокое качество для важных консультаций
                  <br />
                  • Включите подавление шума в шумной среде
                  <br />
                  • Установите автосохранение каждые 1-2 минуты
                </Typography>
              </Alert>
            </Grid>
          </Grid>
        </TabPanel>

        {/* Security Settings Tab */}
        <TabPanel value={activeTab} index={2}>
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                Настройки безопасности и конфиденциальности
              </Typography>
            </Grid>

            <Grid item xs={12}>
              <Alert severity="warning">
                <Typography variant="subtitle2" gutterBottom>
                  Важная информация о медицинских данных:
                </Typography>
                <Typography variant="body2">
                  • Все записи обрабатываются локально
                  <br />
                  • Данные пациентов зашифрованы
                  <br />
                  • Соблюдение требований HIPAA/GDPR
                  <br />
                  • Автоматическое удаление временных файлов
                </Typography>
              </Alert>
            </Grid>

            <Grid item xs={12}>
              <FormControlLabel
                control={<Switch defaultChecked />}
                label="Шифрование данных пациентов"
                disabled
              />
            </Grid>

            <Grid item xs={12}>
              <FormControlLabel
                control={<Switch defaultChecked />}
                label="Локальная обработка аудио"
                disabled
              />
            </Grid>

            <Grid item xs={12}>
              <FormControlLabel
                control={<Switch defaultChecked />}
                label="Автоматическое удаление кэша"
                disabled
              />
            </Grid>

            <Grid item xs={12}>
              <Button variant="outlined" color="error">
                Очистить все данные
              </Button>
            </Grid>
          </Grid>
        </TabPanel>
      </DialogContent>

      <DialogActions>
        <Button onClick={onClose}>
          Отмена
        </Button>
        <Button onClick={onClose} variant="contained">
          Сохранить
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default SettingsDialog;
