import React from 'react';
import {
  Paper,
  Typography,
  Box,
  Button,
  LinearProgress,
  Chip,
  IconButton,
  Tooltip
} from '@mui/material';
import {
  Mic,
  MicOff,
  Stop,
  Pause,
  PlayArrow,
  VolumeUp,
  Equalizer,
  RecordVoiceOver
} from '@mui/icons-material';

const RecordingControls = ({
  isRecording,
  isPaused,
  recordingTime,
  audioLevel,
  onStart,
  onStop,
  onPause,
  sx
}) => {
  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getRecordingStatus = () => {
    if (isRecording && !isPaused) return { text: 'Запись', color: 'error' };
    if (isRecording && isPaused) return { text: 'Пауза', color: 'warning' };
    return { text: 'Остановлена', color: 'default' };
  };

  const status = getRecordingStatus();

  return (
    <Paper elevation={2} sx={{ p: 2, ...sx }}>
      <Typography variant="h6" gutterBottom>
        <RecordVoiceOver sx={{ mr: 1, verticalAlign: 'middle' }} />
        Управление записью
      </Typography>

      {/* Status */}
      <Box display="flex" alignItems="center" justifyContent="space-between" mb={2}>
        <Chip
          label={status.text}
          color={status.color}
          variant="filled"
          icon={isRecording ? <Mic /> : <MicOff />}
        />
        <Typography variant="h6" component="div" fontFamily="monospace">
          {formatTime(recordingTime)}
        </Typography>
      </Box>

      {/* Audio Level Indicator */}
      {isRecording && (
        <Box mb={2}>
          <Box display="flex" alignItems="center" mb={1}>
            <VolumeUp sx={{ mr: 1 }} />
            <Typography variant="body2">
              Уровень звука
            </Typography>
          </Box>
          <LinearProgress
            variant="determinate"
            value={audioLevel}
            color={audioLevel > 80 ? 'error' : audioLevel > 50 ? 'warning' : 'success'}
            sx={{ height: 8, borderRadius: 4 }}
          />
        </Box>
      )}

      {/* Control Buttons */}
      <Box display="flex" gap={1} flexWrap="wrap">
        {!isRecording ? (
          <Button
            variant="contained"
            color="success"
            startIcon={<Mic />}
            onClick={onStart}
            fullWidth
            size="large"
          >
            Начать запись
          </Button>
        ) : (
          <>
            <Button
              variant="contained"
              color={isPaused ? 'success' : 'warning'}
              startIcon={isPaused ? <PlayArrow /> : <Pause />}
              onClick={onPause}
              sx={{ flex: 1 }}
            >
              {isPaused ? 'Продолжить' : 'Пауза'}
            </Button>
            <Button
              variant="contained"
              color="error"
              startIcon={<Stop />}
              onClick={onStop}
              sx={{ flex: 1 }}
            >
              Стоп
            </Button>
          </>
        )}
      </Box>

      {/* Recording Info */}
      {isRecording && (
        <Box mt={2} p={1} bgcolor="action.hover" borderRadius={1}>
          <Typography variant="caption" display="block" color="text.secondary">
            <Equalizer sx={{ fontSize: 16, mr: 0.5, verticalAlign: 'middle' }} />
            Качество: Высокое | Язык: Русский
          </Typography>
          <Typography variant="caption" display="block" color="text.secondary">
            Подавление шума: Включено
          </Typography>
        </Box>
      )}

      {/* Keyboard shortcuts info */}
      <Box mt={2}>
        <Typography variant="caption" color="text.secondary">
          Горячие клавиши:
        </Typography>
        <Typography variant="caption" display="block" color="text.secondary">
          F1 - Начать | F2 - Стоп | F3 - Пауза
        </Typography>
      </Box>
    </Paper>
  );
};

export default RecordingControls;
