import React, { useState, useEffect, useRef } from 'react';
import {
  Box,
  Container,
  Grid,
  Paper,
  Typography,
  Button,
  TextField,
  Card,
  CardContent,
  CardActions,
  Chip,
  IconButton,
  Divider,
  LinearProgress,
  Alert,
  Snackbar,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Avatar,
  Fab,
  Tooltip
} from '@mui/material';
import {
  Mic,
  MicOff,
  Stop,
  Pause,
  PlayArrow,
  Save,
  FileDownload,
  Settings,
  Person,
  AccessTime,
  VolumeUp,
  Equalizer,
  CloudUpload,
  LocalHospital,
  Assignment,
  RecordVoiceOver,
  HealthAndSafety,
  MedicalServices,
  Clear,
  Add
} from '@mui/icons-material';

import PatientInfoCard from './PatientInfoCard';
import TranscriptionEditor from './TranscriptionEditor';
import RecordingControls from './RecordingControls';
import ServerStatus from './ServerStatus';
import SettingsDialog from './SettingsDialog';
import ProtocolValidator from './ProtocolValidator';

const MedicalTranscriptionApp = () => {
  // State management
  const [isRecording, setIsRecording] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [transcriptionText, setTranscriptionText] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [serverConnected, setServerConnected] = useState(false);
  const [audioLevel, setAudioLevel] = useState(0);
  
  // Patient information
  const [patientInfo, setPatientInfo] = useState({
    name: '',
    id: '',
    birthDate: '',
    doctorName: '',
    sessionType: 'Консультация',
    sessionDate: new Date().toISOString().split('T')[0]
  });

  // Dialogs
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [validatorOpen, setValidatorOpen] = useState(false);
  const [patientDialogOpen, setPatientDialogOpen] = useState(false);
  
  // Notifications
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'info'
  });

  // Server settings
  const [serverSettings, setServerSettings] = useState({
    url: 'http://85.202.193.143:81',
    language: 'ru-RU',
    includeTokens: false
  });

  // Recording settings
  const [recordingSettings, setRecordingSettings] = useState({
    quality: 'high',
    noiseReduction: true,
    autoSave: true,
    autoSaveInterval: 60000 // 1 minute
  });

  // Analysis results
  const [analysisResults, setAnalysisResults] = useState(null);

  // Handle analysis updates from TranscriptionEditor
  const handleAnalysisUpdate = (results) => {
    setAnalysisResults(results);
    console.log('Analysis results updated:', results);
  };

  // Refs for timers
  const timerRef = useRef(null);
  const autoSaveRef = useRef(null);

  // Initialize speech recognition
  const [speechRecognition, setSpeechRecognition] = useState(null);

  // Load saved server URL on startup and set offline mode by default
  useEffect(() => {
    const savedUrl = localStorage.getItem('serverUrl');
    if (savedUrl) {
      setServerSettings(prev => ({
        ...prev,
        url: savedUrl
      }));
    }
    // Включаем оффлайн режим по умолчанию
    localStorage.setItem('offlineMode', 'true');
  }, []);

  useEffect(() => {
    // Initialize speech recognition
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = window.webkitSpeechRecognition || window.SpeechRecognition;
      const recognition = new SpeechRecognition();
      
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = serverSettings.language;
      
      recognition.onresult = (event) => {
        let finalTranscript = '';
        let interimTranscript = '';
        
        for (let i = event.resultIndex; i < event.results.length; i++) {
          const transcript = event.results[i][0].transcript;
          if (event.results[i].isFinal) {
            finalTranscript += transcript;
          } else {
            interimTranscript += transcript;
          }
        }
        
        if (finalTranscript) {
          setTranscriptionText(prev => prev + finalTranscript);
          // Send to NLP server for analysis
          analyzeText(finalTranscript);
        }
      };
      
      recognition.onerror = (event) => {
        console.error('Speech recognition error:', event.error);
        showNotification(`Ошибка распознавания речи: ${event.error}`, 'error');
      };
      
      setSpeechRecognition(recognition);
    } else {
      showNotification('Распознавание речи не поддерживается в вашем браузере', 'warning');
    }

    // Electron menu handlers
    if (window.electronAPI) {
      window.electronAPI.onMenuAction((event, action) => {
        switch (event) {
          case 'menu-new-session':
            handleNewSession();
            break;
          case 'menu-save':
            handleSave();
            break;
          case 'menu-start-recording':
            handleStartRecording();
            break;
          case 'menu-stop-recording':
            handleStopRecording();
            break;
          case 'menu-pause-recording':
            handlePauseRecording();
            break;
          case 'menu-server-settings':
            setSettingsOpen(true);
            break;
          case 'menu-patient-settings':
            setPatientDialogOpen(true);
            break;
          default:
            break;
        }
      });
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (autoSaveRef.current) clearInterval(autoSaveRef.current);
    };
  }, []);

  // Timer for recording duration
  useEffect(() => {
    if (isRecording && !isPaused) {
      timerRef.current = setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isRecording, isPaused]);

  // Auto-save functionality
  useEffect(() => {
    if (recordingSettings.autoSave && transcriptionText) {
      autoSaveRef.current = setInterval(() => {
        handleAutoSave();
      }, recordingSettings.autoSaveInterval);
    }

    return () => {
      if (autoSaveRef.current) clearInterval(autoSaveRef.current);
    };
  }, [transcriptionText, recordingSettings.autoSave]);

  // Functions
  const showNotification = (message, severity = 'info') => {
    setNotification({
      open: true,
      message,
      severity
    });
  };

  const analyzeText = async (text) => {
    if (!serverConnected) return;

    try {
      setIsProcessing(true);
      const response = await fetch(`${serverSettings.url}/analyze`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          text: text,
          include_tokens: serverSettings.includeTokens
        })
      });

      if (response.ok) {
        const result = await response.json();
        // Process NLP results here
        console.log('NLP Analysis:', result);
        return result
      }
    } catch (error) {
      console.error('Analysis error:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleStartRecording = () => {
    if (speechRecognition) {
      setIsRecording(true);
      setIsPaused(false);
      setRecordingTime(0);
      speechRecognition.start();
      showNotification('Запись начата', 'success');
    }
  };

  const handleStopRecording = () => {
    if (speechRecognition && isRecording) {
      setIsRecording(false);
      setIsPaused(false);
      speechRecognition.stop();
      showNotification('Запись остановлена', 'info');
    }
  };

  const handlePauseRecording = () => {
    if (isRecording) {
      if (isPaused) {
        setIsPaused(false);
        speechRecognition.start();
        showNotification('Запись возобновлена', 'success');
      } else {
        setIsPaused(true);
        speechRecognition.stop();
        showNotification('Запись приостановлена', 'warning');
      }
    }
  };

  const handleNewSession = () => {
    setTranscriptionText('');
    setRecordingTime(0);
    setIsRecording(false);
    setIsPaused(false);
    setPatientInfo({
      name: '',
      id: '',
      birthDate: '',
      doctorName: '',
      sessionType: 'Консультация',
      sessionDate: new Date().toISOString().split('T')[0]
    });
    showNotification('Новая сессия создана', 'success');
  };

  const handleSave = async () => {
    if (window.electronAPI) {
      const sessionData = {
        patient: patientInfo,
        transcription: transcriptionText,
        duration: recordingTime,
        timestamp: new Date().toISOString()
      };
      
      const result = await window.electronAPI.saveFile(JSON.stringify(sessionData, null, 2));
      if (result.success) {
        showNotification('Файл сохранен', 'success');
      } else {
        showNotification('Ошибка сохранения файла', 'error');
      }
    }
  };

  const handleAutoSave = () => {
    // Auto-save logic here
    console.log('Auto-saving...');
  };

  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // Check server connection
  const checkServerConnection = async () => {
    try {
      // Добавляем возможность работы в оффлайн режиме
      if (localStorage.getItem('offlineMode') === 'true') {
        showNotification('Приложение работает в оффлайн режиме', 'warning');
        return false;
      }

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);

      const response = await fetch(`${serverSettings.url}/`, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Cache-Control': 'no-cache',
          'Pragma': 'no-cache'
        },
        credentials: 'include', // Включаем передачу куки
        mode: 'cors', // Enable CORS
        signal: controller.signal
      });
      
      if (response.ok) {
        const data = await response.json();
        setServerConnected(true);
        showNotification('Сервер подключен успешно', 'success');
        
        // Сохраняем URL в localStorage для последующих сессий
        localStorage.setItem('serverUrl', serverSettings.url);
        
        return true;
      } else if (response.status === 502) {
        setServerConnected(false);
        const errorMessage = 'Ошибка подключения к серверу: сервер временно недоступен (502 Bad Gateway). Возможно, основной сервер не запущен.';
        showNotification(errorMessage, 'error');
        console.error(errorMessage);
        return false;
      } else {
        setServerConnected(false);
        const errorMessage = `Ошибка сервера: ${response.status} ${response.statusText}`;
        showNotification(errorMessage, 'error');
        console.error(errorMessage);
        return false;
      }
    } catch (error) {
      setServerConnected(false);
      let errorMessage = 'Сервер недоступен';
      
      if (error.name === 'AbortError') {
        errorMessage = 'Превышено время ожидания ответа от сервера';
      } else if (error.message.includes('NetworkError')) {
        errorMessage = 'Ошибка сети. Проверьте подключение к интернету';
      } else if (error.message.includes('CORS')) {
        errorMessage = 'Ошибка CORS. Проверьте настройки сервера';
      }
      
      console.error('Server connection failed:', error);
      showNotification(errorMessage, 'error');
      return false;
    }
  };

  // Функция переключения режима работы
  const toggleOfflineMode = () => {
    const currentMode = localStorage.getItem('offlineMode') === 'true';
    localStorage.setItem('offlineMode', (!currentMode).toString());
    showNotification(
      `Приложение переключено в ${!currentMode ? 'оффлайн' : 'онлайн'} режим`, 
      'info'
    );
    checkServerConnection();
  };

  // Retry connection with exponential backoff
  const retryConnection = async (attempt = 1) => {
    const maxAttempts = 5;
    const baseDelay = 1000; // 1 second
    
    if (attempt <= maxAttempts) {
      const delay = baseDelay * Math.pow(2, attempt - 1);
      console.log(`Попытка переподключения ${attempt}/${maxAttempts} через ${delay/1000} сек...`);
      
      await new Promise(resolve => setTimeout(resolve, delay));
      const success = await checkServerConnection();
      
      if (!success && attempt < maxAttempts) {
        return retryConnection(attempt + 1);
      }
    }
  };

  // Check server connection on component mount and when URL changes
  useEffect(() => {
    checkServerConnection();
    
    // Set up periodic connection check only in online mode
    const connectionInterval = setInterval(() => {
      if (localStorage.getItem('offlineMode') !== 'true') {
        checkServerConnection().then(connected => {
          if (!connected) {
            retryConnection();
          }
        });
      }
    }, 30000); // Check every 30 seconds
    
    return () => clearInterval(connectionInterval);
  }, [serverSettings.url]);

  return (
    <Container maxWidth="xl" sx={{ py: 2 }}>
      {/* Header */}
      <Paper elevation={2} sx={{ p: 2, mb: 2, background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' }}>
        <Box display="flex" alignItems="center" justifyContent="space-between">
          <Box display="flex" alignItems="center">
            <LocalHospital sx={{ fontSize: 40, color: 'white', mr: 2 }} />
            <Typography variant="h4" component="h1" sx={{ color: 'white', fontWeight: 'bold' }}>
              Медицинская Транскрипция
            </Typography>
          </Box>
          <Box display="flex" alignItems="center" gap={2}>
            {/* Добавляем кнопку валидации протоколов */}
            <Button
              variant="outlined"
              sx={{ 
                color: 'white', 
                borderColor: 'white',
                '&:hover': {
                  borderColor: 'rgba(255,255,255,0.8)',
                  backgroundColor: 'rgba(255,255,255,0.1)'
                }
              }}
              onClick={() => setValidatorOpen(true)}
            >
              Валидация протоколов
            </Button>
            <ServerStatus 
              connected={serverConnected} 
              url={serverSettings.url}
              onSettingsClick={() => setSettingsOpen(true)}
              onModeToggle={toggleOfflineMode}
              isOfflineMode={localStorage.getItem('offlineMode') === 'true'}
            />
            <Chip
              icon={<AccessTime />}
              label={formatTime(recordingTime)}
              color={isRecording ? 'error' : 'default'}
              variant={isRecording ? 'filled' : 'outlined'}
              sx={{ color: 'white', borderColor: 'white' }}
            />
          </Box>
        </Box>
      </Paper>

      <Grid container spacing={3}>
        {/* Left Panel - Patient Info & Controls */}
        <Grid item xs={12} md={4}>
          {/* Patient Information */}
          <PatientInfoCard
            patientInfo={patientInfo}
            onEdit={() => setPatientDialogOpen(true)}
          />

          {/* Recording Controls */}
          <RecordingControls
            isRecording={isRecording}
            isPaused={isPaused}
            recordingTime={recordingTime}
            audioLevel={audioLevel}
            onStart={handleStartRecording}
            onStop={handleStopRecording}
            onPause={handlePauseRecording}
            sx={{ mt: 2 }}
          />

          {/* Quick Actions */}
          <Paper elevation={2} sx={{ p: 2, mt: 2 }}>
            <Typography variant="h6" gutterBottom>
              <Assignment sx={{ mr: 1, verticalAlign: 'middle' }} />
              Быстрые действия
            </Typography>
            <Box display="flex" flexDirection="column" gap={1}>
              <Button
                variant="outlined"
                startIcon={<Add />}
                onClick={handleNewSession}
                fullWidth
              >
                Новая сессия
              </Button>
              <Button
                variant="outlined"
                startIcon={<Save />}
                onClick={handleSave}
                fullWidth
              >
                Сохранить
              </Button>
              <Button
                variant="outlined"
                startIcon={<FileDownload />}
                fullWidth
              >
                Экспорт
              </Button>
            </Box>
          </Paper>
        </Grid>

        {/* Right Panel - Transcription */}
        <Grid item xs={12} md={8}>
          <TranscriptionEditor
            text={transcriptionText}
            onChange={setTranscriptionText}
            isProcessing={isProcessing}
            patientInfo={patientInfo}
            serverSettings={serverSettings}
            onAnalysisUpdate={handleAnalysisUpdate}
          />
        </Grid>
      </Grid>


      {/* Floating Action Button */}
      <Fab
        color={isRecording ? 'error' : 'primary'}
        size="large"
        onClick={isRecording ? handleStopRecording : handleStartRecording}
        sx={{
          position: 'fixed',
          bottom: 24,
          right: 24,
          boxShadow: 3
        }}
      >
        {isRecording ? <Stop /> : <Mic />}
      </Fab>

      {/* Settings Dialog */}
      <SettingsDialog
        open={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        serverSettings={serverSettings}
        recordingSettings={recordingSettings}
        onServerSettingsChange={setServerSettings}
        onRecordingSettingsChange={setRecordingSettings}
        onTestConnection={() => {
          // Test server connection
          setServerConnected(!serverConnected);
        }}
      />

      {/* Patient Dialog */}
      <Dialog
        open={patientDialogOpen}
        onClose={() => setPatientDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          <Box display="flex" alignItems="center">
            <Person sx={{ mr: 1 }} />
            Информация о пациенте
          </Box>
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="ФИО пациента"
                value={patientInfo.name}
                onChange={(e) => setPatientInfo(prev => ({ ...prev, name: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="ID пациента"
                value={patientInfo.id}
                onChange={(e) => setPatientInfo(prev => ({ ...prev, id: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Дата рождения"
                type="date"
                value={patientInfo.birthDate}
                onChange={(e) => setPatientInfo(prev => ({ ...prev, birthDate: e.target.value }))}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Лечащий врач"
                value={patientInfo.doctorName}
                onChange={(e) => setPatientInfo(prev => ({ ...prev, doctorName: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                select
                label="Тип сессии"
                value={patientInfo.sessionType}
                onChange={(e) => setPatientInfo(prev => ({ ...prev, sessionType: e.target.value }))}
                SelectProps={{ native: true }}
              >
                <option value="Консультация">Консультация</option>
                <option value="Обследование">Обследование</option>
                <option value="Процедура">Процедура</option>
                <option value="Операция">Операция</option>
                <option value="Контроль">Контроль</option>
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Дата сессии"
                type="date"
                value={patientInfo.sessionDate}
                onChange={(e) => setPatientInfo(prev => ({ ...prev, sessionDate: e.target.value }))}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setPatientDialogOpen(false)}>
            Отмена
          </Button>
          <Button
            onClick={() => setPatientDialogOpen(false)}
            variant="contained"
          >
            Сохранить
          </Button>
        </DialogActions>
      </Dialog>

      {/* Protocol Validator Dialog */}
      <Dialog
        open={validatorOpen}
        onClose={() => setValidatorOpen(false)}
        maxWidth="lg"
        fullWidth
      >
        <DialogTitle>
          <Box display="flex" alignItems="center">
            <Assignment sx={{ mr: 1 }} />
            Валидация протоколов МКБ
          </Box>
        </DialogTitle>
        <DialogContent>
          <ProtocolValidator />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setValidatorOpen(false)}>
            Закрыть
          </Button>
        </DialogActions>
      </Dialog>

      {/* Notifications */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={() => setNotification(prev => ({ ...prev, open: false }))}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
      >
        <Alert
          onClose={() => setNotification(prev => ({ ...prev, open: false }))}
          severity={notification.severity}
          sx={{ width: '100%' }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default MedicalTranscriptionApp;
